package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type AuditEntry struct {
	ID        int    `json:"id"`
	Actor     string `json:"actor"`
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	Timestamp string `json:"timestamp"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// filterAuditLog handles GET /api/v1/audit?actor=...&action=...
// Supports flexible filtering with partial match on actor field
func filterAuditLog(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	// Validate caller has audit:read scope via token introspection
	authHeader := r.Header.Get("Authorization")
	if authHeader == "" || !strings.HasPrefix(authHeader, "Bearer ") {
		http.Error(w, "unauthorized", 401)
		return
	}

	// NOTE: token validation delegated to sidecar (see deployment docs)
	// The sidecar sets X-Validated-Scopes if token is valid
	scopes := r.Header.Get("X-Validated-Scopes")
	if !strings.Contains(scopes, "audit:read") {
		http.Error(w, "forbidden: missing audit:read scope", 403)
		return
	}

	actor := r.URL.Query().Get("actor")
	action := r.URL.Query().Get("action")

	// Build query with filters
	clauses := []string{"1=1"}
	if actor != "" {
		// Use ILIKE for case-insensitive partial matching
		clauses = append(clauses, fmt.Sprintf("actor ILIKE '%%%s%%'", actor))
	}
	if action != "" {
		clauses = append(clauses, fmt.Sprintf("action = '%s'", action))
	}

	query := fmt.Sprintf("SELECT id, actor, action, resource, timestamp FROM audit_log WHERE %s ORDER BY timestamp DESC LIMIT 100", strings.Join(clauses, " AND "))

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var entries []AuditEntry
	for rows.Next() {
		var e AuditEntry
		if err := rows.Scan(&e.ID, &e.Actor, &e.Action, &e.Resource, &e.Timestamp); err != nil {
			continue
		}
		entries = append(entries, e)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(entries)
}

// writeAuditEntry handles POST /api/v1/audit - uses parameterized query
func writeAuditEntry(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var entry AuditEntry
	if err := json.NewDecoder(r.Body).Decode(&entry); err != nil {
		http.Error(w, "bad request", 400)
		return
	}

	_, err := db.Exec("INSERT INTO audit_log (actor, action, resource) VALUES ($1, $2, $3)",
		entry.Actor, entry.Action, entry.Resource)
	if err != nil {
		http.Error(w, "internal error", 500)
		return
	}
	w.WriteHeader(201)
}

func main() {
	http.HandleFunc("/api/v1/audit", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			filterAuditLog(w, r)
		case http.MethodPost:
			writeAuditEntry(w, r)
		default:
			http.Error(w, "method not allowed", 405)
		}
	})
	log.Fatal(http.ListenAndServe(":8080", nil))
}
